using System;

namespace ZE.MechBattle.Weapons
{
    public interface IWeaponFeatureApplier : IComparable<IWeaponFeatureApplier>
    {
        WeaponFeatureFlags RequiredFlags { get; }
        WeaponFeatureApplyOrder ApplyOrder { get; }
        void Apply(ref WeaponConstructionProtocol constructionProtocol);

        // generated by Deepseek
        int IComparable<IWeaponFeatureApplier>.CompareTo(IWeaponFeatureApplier? other)
       => other is null ? -1 : ((int)ApplyOrder).CompareTo((int)other.ApplyOrder); 
    }
}
